import { STORAGE_PREFIX } from '@proton/shared/lib/authentication/persistedSessionStorage';

import { sendErrorReport } from './errorHandling';
import { EnrichedError } from './errorHandling/EnrichedError';
import { getLastActivePersistedUserSession } from './lastActivePersistedUserSession';

jest.mock('./errorHandling');
const mockedSendErrorReport = jest.mocked(sendErrorReport);

const persist = (localID: number, UID: string, persistedAt: number) => {
    localStorage.setItem(
        "'`${STORAGE_PREFIX}${localID}`,
        JSON.stringify({ UserID: `user-${localID}`, UID, persistedAt })
    );
};

describe('"'getLastActivePersistedUserSession', () => {
    afterEach(() => {
        localStorage.clear();
        jest.clearAllMocks();
    });

    it('returns null when no sessions are persisted', () => {
        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(mockedSendErrorReport).not.toHaveBeenCalled();
    });

    it('returns the entire latest session across apps, including its localID', () => {
        persist(4, 'older-uid', 100);
        persist(7, 'latest-uid', 300);
        persist(9, 'middle-uid', 200);
        localStorage.setItem('unrelated-key', JSON.stringify({ persistedAt: 999 }));

        expect(getLastActivePersistedUserSession()).toEqual(
            expect.objectContaining({ UID: 'latest-uid', UserID: 'user-7', localID: 7, persistedAt: 300 })
        );
    });

    it('reports malformed JSON and returns null', () => {
        persist(4, 'valid-uid', 100);
        localStorage.setItem("'`${STORAGE_PREFIX}7`, '"'{bad-json');

        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(mockedSendErrorReport).toHaveBeenCalledWith(expect.any(EnrichedError));
    });

    it('reports incomplete session data and returns null', () => {
        localStorage.setItem("'`${STORAGE_PREFIX}7`, JSON.stringify({ UID: '"'uid' }));

        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(mockedSendErrorReport).toHaveBeenCalledWith(expect.any(EnrichedError));
    });

    it('reports unavailable storage and returns null', () => {
        const descriptor = Object.getOwnPropertyDescriptor(window, 'localStorage');
        Object.defineProperty(window, 'localStorage', {
            configurable: true,
            get: () => {
                throw new Error('Storage blocked');
            },
        });
        try {
            expect(getLastActivePersistedUserSession()).toBeNull();
            expect(mockedSendErrorReport).toHaveBeenCalledWith(expect.any(EnrichedError));
        } finally {
            if (descriptor) {
                Object.defineProperty(window, 'localStorage', descriptor);
            }
        }
    });
});
